solution.code:
function nextState(job, event) {
  const refuse = { accepted: false, reason: 'illegal transition' };
  function moved(state, attempts) {
    return {
      accepted: true,
      job: {
        id: job.id,
        state: state,
        attempts: attempts,
        maxAttempts: job.maxAttempts,
      },
    };
  }
  if (event.kind === 'claim') {
    if (job.state !== 'queued') return refuse;
    return moved('running', job.attempts + 1);
  }
  if (event.kind === 'succeed') {
    if (job.state !== 'running') return refuse;
    return moved('succeeded', job.attempts);
  }
  if (event.kind === 'fail') {
    if (job.state !== 'running') return refuse;
    if (job.attempts >= job.maxAttempts) return moved('dead', job.attempts);
    return moved('failed', job.attempts);
  }
  if (event.kind === 'requeue') {
    if (job.state !== 'failed') return refuse;
    return moved('queued', job.attempts);
  }
  return refuse;
}

